import{z as B,x as E,o,c as p,q as i,j as n,D as d,d as l,s as r,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const x=JSON.parse('{"title":"到达定义","description":"","frontmatter":{"title":"到达定义","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/reaching-def.md","filePath":"cs/reaching-def.md","lastUpdated":1791413859000}'),c={name:"cs/reaching-def.md"};function A(u,e,f,m,h,D){const t=E("Mermaid");return o(),p("div",null,[e[2]||(e[2]=i('<h1 id="到达定义" tabindex="-1">到达定义 <a class="header-anchor" href="#到达定义" aria-label="Permalink to &quot;到达定义&quot;">​</a></h1><div class="epigraph"><p>定值 $d$ 到达点 $p$，当存在一条从 $d$ 到 $p$ 的路，路上 $d$ 所写的名字不被杀掉。这是向前的并汇合数据流。</p><footer>—— 据龙书第 9 章整理</footer></div><p>上一课<a href="/cs/dataflow-liveness">活跃变量与数据流</a>用后向 <code>use</code>/<code>def</code> 钉了框架与冲突图入口，并声明到达定值向前、可用表达式另套 gen/kill。本课不重写活跃方程。缺口是<strong>哪一次写</strong>还能被这里读到：常量传播、未初始化使用、SSA 之前的 def-use 链，都靠到达。后课可用表达式把「算过且未被杀掉的表达式」换成交汇合。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>每条对 \\(x\\) 的赋值是一个定值。<code>gen[B]</code>：块内最后写下的那些定值。<code>kill[B]</code>：被块内新写杀掉的、对同名的其他定值。方程：<code>in[B]=\\bigcup_{前驱} out[P]</code>，<code>out[B]=gen[B]\\cup(in[B]-kill[B])</code>。从空集迭代到不动点。与活跃相反：信息沿控制流正向走，汇合是并（任一路带来的定值都算到达）。</p><p><span class="marginnote">数字实例：块内三句 <code>d1: x=a+1; d2: y=x; d3: x=b+2</code>，则 gen[B]={d2,d3}（x 的最后写是 d3、y 的最后写是 d2，两条都活着出块），kill[B]={d1}（对 x 的新写抹掉了 d1 的到达权；d2 写的是别的名字，不杀任何人）。gen/kill 就是在问「这个块出口处谁还活着、谁被它处决了」。</span></p><p>缺口是这套 gen/kill，不是再解释格。未初始化：入口虚构定值 \\(\\bot\\)，若 \\(\\bot\\) 到达某次读，则可能未定义。SSA 上每个使用对应一条定值（φ 除外看成多条），到达分析几乎退化；本课覆盖非 SSA 与 SSA 前的 IR。</p><h3 id="到达不是「必须到达」" tabindex="-1">到达不是「必须到达」 <a class="header-anchor" href="#到达不是「必须到达」" aria-label="Permalink to &quot;到达不是「必须到达」&quot;">​</a></h3><p>并汇合是 may：存在一条路。必须到达要用交，那是另一分析。不要用到达去做「所有路都经过这次写」。</p><p><span class="marginnote">龙书 9.2.4 节到达定值。Kildall 的格框架上一课已点。常量传播把到达的唯一常量定值替换掉；多条定值到达则放弃。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>给每个赋值编号。算块的 gen/kill。正向迭代。指令级可再拆：每条指令后的到达集。复杂度与活跃同类：集大小 × 块数 × 轮数。</p>',12)),(o(),n(s,null,{default:d(()=>[r(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEF%5B%22%E5%AE%9A%E5%80%BC%E7%BC%96%E5%8F%B7%22%5D%20--%3E%20GK%5B%22gen%20%2F%20kill%22%5D%0A%20%20GK%20--%3E%20FP%5B%22%E5%89%8D%E5%90%91%E5%B9%B6%EF%BC%9A%E4%B8%8D%E5%8A%A8%E7%82%B9%22%5D%0A%20%20FP%20--%3E%20DU%5B%22def-use%20%E9%93%BE%22%5D%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("p",null,"def-use：对每个使用，到达此处的该名定值列表。SSA 把列表长度压到 1（φ 的操作数分开）。",-1)),e[4]||(e[4]=a("p",null,[a("span",{class:"marginnote"},[l("常见误区：初学者容易把「\\(d\\) 到达 \\(p\\)」读成「运行时 \\(d\\) 一定执行过」。到达是 may 语义：只要"),a("strong",null,"存在"),l("一条从 \\(d\\) 到 \\(p\\) 且不杀 \\(d\\) 的路径就算到达——哪怕那条路一次都不会被执行。「所有路径都保证经过」是 must 语义，要用交汇合（可用表达式那一族），两者不能混用。")])],-1)),e[5]||(e[5]=a("h2",{id:"机制",tabindex:"-1"},[l("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[6]||(e[6]=a("p",null,"死写：定值到达的使用集为空（且无副作用）可删——与活跃对偶。拷贝传播：到达的唯一 \\(x\\leftarrow y\\) 且 \\(y\\) 未被改。本课点名，不写完全部改写规则。",-1)),e[7]||(e[7]=a("p",null,"指针别名使 kill 不精确：保守少杀，到达集偏大，优化变少，不错语义。",-1)),(o(),n(s,null,{default:d(()=>[r(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20B1%5B%22B1%EF%BC%9Ad1%20%E5%AE%9A%E4%B9%89%20x%3D1%22%5D%20--%3E%20BR%7B%22if%20%E5%88%86%E6%94%AF%22%7D%0A%20%20BR%20--%3E%7C%22then%22%7C%20B3%5B%22B3%EF%BC%9Ad2%20%E5%AE%9A%E4%B9%89%20x%3D2%EF%BC%8C%E6%9D%80%E6%8E%89%20d1%22%5D%0A%20%20BR%20--%3E%7C%22else%22%7C%20B4%5B%22B4%EF%BC%9A%E4%B8%8D%E7%A2%B0%20x%EF%BC%8Cd1%20%E4%BB%8D%E5%88%B0%E8%BE%BE%22%5D%0A%20%20B3%20--%3E%20M%5B%22B5%EF%BC%9A%E8%AF%BB%20x%22%5D%0A%20%20B4%20--%3E%20M%0A%20%20M%20--%3E%20R%5B%22%E5%88%B0%E8%BE%BE%E9%9B%86%E6%98%AF%E5%B9%B6%EF%BC%9A%7Bd1%2C%20d2%7D%EF%BC%8Cx%20%E5%8F%AF%E8%83%BD%201%20%E4%B9%9F%E5%8F%AF%E8%83%BD%202%22%5D%0A"})]),fallback:d(()=>[...e[1]||(e[1]=[l(" Loading... ",-1)])]),_:1})),e[8]||(e[8]=i('<p><span class="marginnote">直觉类比：kill 像「注销旧门牌」——同一栋房子换了户主，旧户主的信就再也送不到。指针别名的问题是：你看见 <code>*p = 2</code> 却不知道 <code>p</code> 指向谁，只好假设它可能就是 <code>x</code> 的地址，于是不敢注销任何人——信箱里旧信越积越多（到达集偏大），能做的优化随之变少，但永远不会送错信。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不做可用表达式、不着色、不选指令。后课默认：能回答「哪些写到达这里」。可用表达式用交、问的是表达式而非定值编号，下一缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>到达定值：前向、并、gen/kill。</li><li>may 语义；未初始化用入口 \\(\\bot\\)。</li><li>SSA 使 def-use 变薄，分析仍对非 SSA 成立。</li><li>出处：Aho et al., 龙书第 9 章。</li></ul>',5))])}const C=B(c,[["render",A]]);export{x as __pageData,C as default};
